<script setup lang="ts">import{ref}from'vue';import{Search}from'@element-plus/icons-vue';import{api,type Verb,type Form}from'../services/api';const q=ref('帰る'),options=ref<Verb[]>([]),verb=ref<Verb>(),forms=ref<Form[]>([]),chosen=ref<Form>(),aiText=ref(''),loading=ref(false);
async function search(){options.value=(await api.get('/verbs/search',{params:{q:q.value}})).data;if(options.value[0])select(options.value[0])}async function select(v:Verb){let d=(await api.get('/verbs/'+v.id)).data;verb.value=d.verb;forms.value=d.conjugations;chosen.value=undefined;aiText.value=''}async function explain(f:Form){chosen.value=f;loading.value=true;aiText.value=(await api.post('/ai/explain',{lemma:verb.value!.lemma,form:f.chineseName,correct:f.value})).data.explanation;loading.value=false}</script>
<template><div class="eyebrow">活用查询</div><h1 class="page-title">查清变化，而不只是查到答案。</h1><el-input v-model="q" class="searchbox" size="large" placeholder="输入汉字或假名，例如：帰る" @keyup.enter="search"><template #append><el-button :icon="Search" @click="search"/></template></el-input>
<div v-if="options.length>1" style="margin-bottom:16px"><el-button v-for="o in options" :key="o.id" @click="select(o)">{{o.lemma}}・{{o.reading}}</el-button></div>
<div v-if="verb" class="card"><div class="verb-head"><h2>{{verb.lemma}}</h2><div><b>{{verb.reading}}</b><p class="muted">{{verb.meanings}}</p></div><span class="tag">{{verb.verbClass}}</span></div>
<div class="forms"><div v-for="f in forms" :key="f.type" class="form" @click="explain(f)"><small>{{f.displayName}} <i v-if="f.exception">例外</i></small><b>{{f.value}}</b></div></div></div>
<el-drawer v-model="chosen" size="min(520px,90%)" :title="chosen?.displayName"><template v-if="chosen"><h2>{{verb?.lemma}} → {{chosen.value}}</h2><p class="muted">{{chosen.japaneseName}} · {{chosen.explanation}}</p><div class="steps"><div v-for="s in chosen.steps" :key="s">{{s}}</div></div><el-divider/><h3>AI 中文解释</h3><div v-loading="loading" style="white-space:pre-wrap;line-height:1.8">{{aiText}}</div></template></el-drawer>
<el-empty v-if="!verb" description="输入一个动词开始查询"/></template>
